```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH a AS (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.src, count(*) n, round(avg(c.duration/1e6),1) client_ms, round(avg(s.duration/1e6),2) rate_server_ms, round(avg(epoch(s.time) - epoch(c.time))*1000,1) start_gap_ms FROM a c JOIN a s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id AND s.service_name='rate' AND s.attr_span_kind='Server' WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' AND c.attr_span_kind='Client' GROUP BY c.src",
          "claim": "search's client calls to rate take about 1494 ms in abnormal vs 0.7 ms normal; rate's server span is still about 0.6 ms, and the wait occurs before it starts."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, round(approx_quantile(duration,0.95)/1e6,1) p95_ms, count(*) n FROM abnormal_traces WHERE (service_name='search' AND span_name IN ('geo.Geo/Nearby','rate.Rate/GetRates')) OR (service_name='rate' AND attr_span_kind='Server') GROUP BY ALL ORDER BY 1,2,3",
          "claim": "Within abnormal traffic, search's geo calls stay at about 0.6 ms p95 while only its rate calls grow to about 1.5 s; rate's server spans stay near 1 ms."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, round(approx_quantile(duration,0.95)/1e6,1) p95_ms, count(*) n FROM abnormal_traces WHERE (service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') AND attr_span_kind IN ('Server','Client')) OR (service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server') GROUP BY ALL ORDER BY 1,2,3",
          "claim": "search.Search/Nearby server p95 ~1526 ms propagates to frontend's search client call and to frontend HTTP /hotels, both ~1524 ms p95."
        }
      ]
    }
  ]
}
```

